def source(path,needle=None,line=None):
 p=root/path;ls=p.read_text().splitlines()
 if line is None:
  line=next((i for i,l in enumerate(ls,1) if needle in l),None)
  if line is None:raise ValueError((path,needle))
 assert 0<line<=len(ls)
 return {'path':path,'line':line}
def item(id,title,intent,status,sources,**kw):
 return {'id':id,'title':title,'intent':intent,'status':status,'historical':True,'sources':sources,**kw}
def s(p,n):return source(p,n)
